// ── CONFIGURACIÓN ────────────────────────────────────────────────
const DEBUG = false;
function dbg(msg) { if (DEBUG) node.warn(msg); }

// ── FILTRO 1: ignorar mensajes de status MQTT ────────────────────
let raw = msg.payload;
if (raw === "online" || raw === "offline") return null;

// ── Parseo ───────────────────────────────────────────────────────
let p = raw;
if (Buffer.isBuffer(p)) p = p.toString();
if (typeof p === "string") {
    try { p = JSON.parse(p); }
    catch (err) { dbg("Payload no es JSON válido: " + p); return null; }
}
if (!p || typeof p !== "object") { dbg("Payload inválido"); return null; }
if (!p.sensors || typeof p.sensors !== "object") { dbg("Falta objeto sensors"); return null; }

// ── Metadatos ────────────────────────────────────────────────────
let deviceId = p.device_id || "desconocido";
let zone = p.zone || "sin_zona";

// ── FILTRO 2: ignorar device_id con formato antiguo (datos retain) ──
if (deviceId.startsWith("ESP32_Node") || deviceId.startsWith("device_")) {
    dbg("Ignorando device_id con formato antiguo: " + deviceId);
    return null;
}

// ── Timestamp ────────────────────────────────────────────────────
let timestamp = p.timestamp || Math.floor(Date.now() / 1000);
if (typeof timestamp === "string") {
    let n = Number(timestamp);
    if (!isNaN(n)) { timestamp = n; }
    else {
        let d = Date.parse(timestamp);
        timestamp = !isNaN(d) ? Math.floor(d / 1000) : Math.floor(Date.now() / 1000);
    }
}
let timestampMs = timestamp * 1000;

// ── Sensores ─────────────────────────────────────────────────────
let s = p.sensors;
let temperatura = s.temperature_c ?? null;
let humedad = s.humidity_pct ?? null;
let lightRaw = s.light_raw ?? null;
let gasDetected = s.gas_detected ?? null;
let gasMq2Raw = s.gas_mq2_raw ?? null;
let gasMq2Voltage = s.gas_mq2_voltage ?? null;
let gasMq2Percent = s.gas_mq2_percent ?? null;
let gasMq2Ratio = s.gas_mq2_ratio ?? null;
let gasMq2PpmEst = s.gas_mq2_ppm_est ?? null;

// ── Aviso campos faltantes (solo en modo debug) ──────────────────
if (DEBUG) {
    let faltantes = [];
    if (temperatura === null) faltantes.push("temperature_c");
    if (humedad === null) faltantes.push("humidity_pct");
    if (lightRaw === null) faltantes.push("light_raw");
    if (gasDetected === null) faltantes.push("gas_detected");
    if (gasMq2Raw === null) faltantes.push("gas_mq2_raw");
    if (gasMq2Voltage === null) faltantes.push("gas_mq2_voltage");
    if (gasMq2Percent === null) faltantes.push("gas_mq2_percent");
    if (gasMq2Ratio === null) faltantes.push("gas_mq2_ratio");
    if (gasMq2PpmEst === null) faltantes.push("gas_mq2_ppm_est");
    if (faltantes.length > 0) dbg("Faltan campos para " + deviceId + ": " + faltantes.join(", "));
    dbg("device_id: " + deviceId + " | zone: " + zone);
}

// ── Salida InfluxDB  [fields, tags, timestamp] ───────────────────
let fields = { temperatura, humedad, lightRaw, gasDetected, gasMq2Raw, gasMq2Voltage, gasMq2Percent, gasMq2Ratio, gasMq2PpmEst };
Object.keys(fields).forEach(k => { if (fields[k] === null) delete fields[k]; })

let msgInflux = {
    measurement: "telemetria_ambiental",
    payload: [
        {
            temperature_c: temperatura,
            humidity_pct: humedad,
            light_raw: lightRaw,
            gas_detected: gasDetected !== null ? (gasDetected ? 1 : 0) : null,
            gas_mq2_raw: gasMq2Raw,
            gas_mq2_voltage: gasMq2Voltage,
            gas_mq2_percent: gasMq2Percent,
            gas_mq2_ratio: gasMq2Ratio,
            gas_mq2_ppm_est: gasMq2PpmEst
        },
        {
            device_id: String(deviceId),
            zone: String(zone)
        },
        timestampMs
    ]
};

// ── Salida MongoDB ───────────────────────────────────────────────
let msgMongo = {
    payload: {
        device_id: deviceId,
        zone: zone,
        topic: msg.topic,
        timestamp: timestamp,
        sensors: {
            temperature_c: temperatura,
            humidity_pct: humedad,
            light_raw: lightRaw,
            gas_detected: gasDetected,
            gas_mq2_raw: gasMq2Raw,
            gas_mq2_voltage: gasMq2Voltage,
            gas_mq2_percent: gasMq2Percent,
            gas_mq2_ratio: gasMq2Ratio,
            gas_mq2_ppm_est: gasMq2PpmEst
        }
    }
};

return [msgInflux, msgMongo];

let s = msg.payload.sensors;

if (!s) return null;

const UMBRALES = {
    temperature_c: { max: 35 },
    humidity_pct: { max: 90 },
    gas_mq2_ppm_est: { max: 200 }
};

let alertas = [];
for (let campo in UMBRALES) {
    let val = s[campo];
    let u = UMBRALES[campo];
    if (val === null || val === undefined) continue;
    if (u.max !== undefined && val > u.max)
        alertas.push({ field: campo, value: val, threshold: u.max, op: ">" });
    if (u.min !== undefined && val < u.min)
        alertas.push({ field: campo, value: val, threshold: u.min, op: "<" });
}

// Si no hay alertas, no insertar nada
if (alertas.length === 0) return null;

msg.payload = {
    device_id: msg.payload.device_id,
    zone: msg.payload.zone,
    triggered_at: new Date(msg.payload.timestamp * 1000),
    alerts: alertas,
    notified_via: [],
    resolved_at: null
};

return msg;

let p = msg.payload;

if (!p || typeof p !== "object" || Array.isArray(p)) {
    node.warn("Payload inválido para device-upsert");
    node.warn(JSON.stringify(p));
    return null;
}

if (!p.device_id) {
    node.warn("No existe device_id en el payload");
    node.warn(JSON.stringify(p));
    return null;
}

let now = new Date(); //.toISOString();

msg.query = {
    device_id: p.device_id
};

msg.payload = {
    $set: {
        device_id: p.device_id,
        zone: p.zone || "Sin_zona",
        topic: p.topic || msg.topic,
        status: "online",
        last_seen: now,
        last_seen_epoch: p.timestamp || Math.floor(Date.now() / 1000),
        sensors: Object.keys(p.sensors || {}),
        updated_at: now
    },
    $setOnInsert: {
        created_at: now
    }
};

return msg;

msg.payload = {
    error: msg.error.message,
    nodo: msg.error.source.name || msg.error.source.id,
    tipo: msg.error.source.type,
    fecha: new Date().toISOString
};

node.warn("Error en " + msg.payload.nodo + ":" + msg.payload.error);

return msg;

// Formatear mensaje de alerta para Telegram
let alerta = msg.payload.alerts[0];
let device = msg.payload.device_id;
let zona = msg.payload.zone;

msg.payload = {
    chatId: 6225327992,
    type: "message",
    content: `🚨 *ALERTA IoT - TFM*\n\n` +
        `📍 Dispositivo: ${device}\n` +
        `🗺️ Zona: ${zona}\n` +
        `⚠️ Variable: ${alerta.field}\n` +
        `📊 Valor: ${alerta.value.toFixed(2)}\n` +
        `🔴 Umbral: ${alerta.threshold}\n` +
        `🕐 ${new Date().toLocaleString('es-ES')}`,
    parse_mode: "Markdown"
};

return msg;

// Control anti-spam: máximo 1 alerta cada 10 minutos por dispositivo
const INTERVALO_MIN = 10;
const ahora = Date.now();

// Recuperar registro de últimas alertas enviadas
let ultimasAlertas = flow.get("ultimasAlertas") || {};

let deviceId = msg.payload.device_id;
let campo = msg.payload.alerts[0].field;
let clave = `${deviceId}_${campo}`;

let ultimaVez = ultimasAlertas[clave] || 0;
let minutosTranscurridos = (ahora - ultimaVez) / 60000;

if (minutosTranscurridos < INTERVALO_MIN) {
    let minutosRestantes = (INTERVALO_MIN - minutosTranscurridos).toFixed(1);
    node.warn(`Anti-spam: alerta ${clave} bloqueada, faltan ${minutosRestantes} min`);
    return null; // bloquear notificación
}

// Actualizar timestamp de última alerta enviada
ultimasAlertas[clave] = ahora;
flow.set("ultimasAlertas", ultimasAlertas);

return msg;
